static void ck(cudaError_t x){if(x!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(x));}
static void raw(const std::string&p,const void*v,size_t n){std::ofstream f(p,std::ios::binary);f.write((const char*)v,n);if(!f)throw std::runtime_error("Artifactwritefailed:"+p);}
static size_t span(const void*p,size_t type){if(!p)return 0;uintptr_t u=(uintptr_t)p;for(auto&a:allocations)if(u>=(uintptr_t)a.p&&u<(uintptr_t)a.p+a.bytes)return((uintptr_t)a.p+a.bytes-u)/type;throw std::runtime_error("Callbackpointeroutsideactualallocation");}
cudaError_t mm_malloc(void**p,size_t bytes){auto e=cudaMalloc(p,bytes);if(e!=cudaSuccess)return e;std::vector<std::string>names={"dVals","dFbrPtr0","dFbrIdx0","dfbrPtr1","dFbrIdx1","dFbrLikeSlcInds"};if(ndim==3)names.push_back("dInds2");else{names.push_back("dFbrIdx2");names.push_back("dFbrPtr2");names.push_back("dInds3");}names.push_back("dU");size_t k=allocations.size();if(k>=names.size())throw std::runtime_error("Unexpectednativeallocation");allocations.push_back({*p,bytes,names[k],(k==0||k+1==names.size())?4:8});return e;}
cudaError_t mm_free(void*p){auto it=std::find_if(allocations.begin(),allocations.end(),[&](auto&a){return a.p==p;});if(it==allocations.end())throw std::runtime_error("Unregisterednativefree");auto e=cudaFree(p);if(e==cudaSuccess)allocations.erase(it);return e;}
static MMLaunch packet(int op,uint32_t grid,uint32_t block,const std::array<const void*,12>&ptr,size_t nf,size_t mode,size_t r,size_t w,int log,int fpw,int lfpw){MMLaunch p{};p.op=op;p.grid=grid;p.block=block;p.ndims=ndim;p.nfibers=nf;p.mode=mode;p.rank=r;p.wps=w;p.logWPC=log;p.fpw=fpw;p.logFPW=lfpw;for(int j=0;j<12;j++){p.pointers[j]=ptr[j];p.lengths[j]=span(ptr[j],j==0||j>=8?4:8);}return p;}
MMLaunch mm_make3(int op,uint32_t grid,uint32_t block,const float*v,const size_t*l,const size_t*i,const size_t*p0,const size_t*p1,const size_t*i1,size_t n,float*u0,const float*u1,const float*u2,size_t mode,size_t r,size_t w,int log,int fpw,int lfpw){return packet(op,grid,block,{v,l,i,p0,p1,i1,nullptr,nullptr,u0,u1,u2,nullptr},n,mode,r,w,log,fpw,lfpw);}
MMLaunch mm_make4(int op,uint32_t grid,uint32_t block,const float*v,const size_t*l,const size_t*i,const size_t*p0,const size_t*p1,const size_t*i1,const size_t*p2,const size_t*i2,size_t n,float*u0,const float*u1,const float*u2,const float*u3,size_t mode,size_t r,size_t w,int log,int fpw,int lfpw){return packet(op,grid,block,{v,l,i,p0,p1,i1,p2,i2,u0,u1,u2,u3},n,mode,r,w,log,fpw,lfpw);}
void mm_dispatch(const MMLaunch&original){MMLaunch p=original;if(p.op<0||p.op>=7)throw std::runtime_error("Invalidop");if(!double_out||p.pointers[8]!=original_output)throw std::runtime_error("Separateoutputaliascontract");for(int j=9;j<12;j++)if(p.pointers[j]==p.pointers[8]&&p.pointers[j])throw std::runtime_error("Inputoutputalias");p.pointers[8]=double_out;p.lengths[8]=double_count;dispatch_counts[p.op]++;if(mm_callback){if(mm_callback(&p))throw std::runtime_error("JuliaGPUcallbackrejected");}else mm_native_launch(p);}
void mm_begin_case(const Tensor&x,Matrix*,const Options&o){Observe timer;if(!allocations.empty())throw std::runtime_error("Unexpectedliveallocationsatcasestart");ndim=x.ndims;mm_rank=o.R;dims.assign(x.dims,x.dims+ndim);offsets.assign(ndim+1,0);for(int m=0;m<ndim;m++)offsets[m+1]=offsets[m]+dims[m]*mm_rank;coo.resize(x.totNnz);for(size_t j=0;j<x.totNnz;j++){for(int m=0;m<ndim;m++){if(x.inds[m][j]>=dims[m])throw std::runtime_error("OriginalCOObound");coo[j].i[m]=x.inds[m][j];}coo[j].v=x.vals[j];if(!std::isfinite(coo[j].v))throw std::runtime_error("Nonfiniteinputtensor");}reports.push_back({case_name,ndim,mm_rank,x.totNnz});prefix.insert(prefix.end(),{double(case_id),double(ndim),double(x.totNnz),double(mm_rank),double(o.warpPerSlice),double(o.fiberPerWarp),double(o.fbrThreashold)});for(auto n:dims)prefix.push_back(n);}
static std::vector<std::vector<char>>read_buffers(){std::vector<std::vector<char>>all;for(auto&a:allocations){all.emplace_back(a.bytes);ck(cudaMemcpy(all.back().data(),a.p,a.bytes,cudaMemcpyDeviceToHost));}return all;}
static std::vector<std::vector<char>>&canonical(){auto it=canonical_cache.find(case_name);if(it!=canonical_cache.end())return it->second;std::string path=canonical_dir+"/actual_input_"+case_name+".bin";std::vector<std::vector<char>>data;if(prepare&&!fs::exists(path)){data=read_buffers();std::ofstream f(path,std::ios::binary);uint64_t magic=0x4d4d435346494e50,n=data.size();f.write((char*)&magic,8);f.write((char*)&n,8);for(size_t k=0;k<data.size();k++){uint64_t bytes=data[k].size(),kind=allocations[k].kind;f.write((char*)&bytes,8);f.write((char*)&kind,8);f.write(data[k].data(),bytes);}if(!f)throw std::runtime_error("Canonicalwritefailure");}else{std::ifstream f(path,std::ios::binary);uint64_t magic=0,n=0;f.read((char*)&magic,8);f.read((char*)&n,8);if(!f||magic!=0x4d4d435346494e50||n!=allocations.size())throw std::runtime_error("Missing/badactualcanonicalinput");for(size_t k=0;k<n;k++){uint64_t bytes=0,kind=0;f.read((char*)&bytes,8);f.read((char*)&kind,8);if(bytes!=allocations[k].bytes||kind!=allocations[k].kind)throw std::runtime_error("Canonicalinputshape");data.emplace_back(bytes);f.read(data.back().data(),bytes);}if(!f)throw std::runtime_error("Truncatedactualcanonicalinput");}return canonical_cache.emplace(case_name,std::move(data)).first->second;}
static void check_inputs(bool initial){auto&ref=canonical();auto got=read_buffers();if(ref.size()!=got.size())throw std::runtime_error("Inputbuffercount");for(size_t j=0;j<got.size();j++)if((initial||allocations[j].name!="dU")&&got[j]!=ref[j]){raw(aux_dir+"/rejected_actual_input_"+case_name+"_"+allocations[j].name+".bin",got[j].data(),got[j].size());throw std::runtime_error("Actualinputbits/readonlytensorchanged:"+allocations[j].name);}}
void mm_mode_begin(int mode,float*dU,const unsigned int*,const TiledTensor*parts){ck(cudaDeviceSynchronize());if(double_base)throw std::runtime_error("LivepreviousmodeDoubleOut");if(mm_rank>32)throw std::runtime_error("Secondaryrankgreaterthan32notcertified");double_count=dims[mode]*mm_rank;original_output=dU+offsets[mode];std::vector<double> initial(double_count+2*GUARD,0);std::fill(initial.begin(),initial.begin()+GUARD,GUARD_VALUE);std::fill(initial.end()-GUARD,initial.end(),GUARD_VALUE);ck(cudaMalloc((void**)&double_base,initial.size()*8));double_out=double_base+GUARD;ck(cudaMemcpy(double_base,initial.data(),initial.size()*8,cudaMemcpyHostToDevice));ck(cudaDeviceSynchronize());Observe timer;std::vector<double> actual(initial.size());ck(cudaMemcpy(actual.data(),double_base,actual.size()*8,cudaMemcpyDeviceToHost));if(actual!=initial)throw std::runtime_error("ActualDoubleOutinitialbits");prefix.insert(prefix.end(),actual.begin(),actual.end());if(mode==0){mm_check_csf(parts,ndim,dims,coo,prepare);check_inputs(true);if(prepare){std::ofstream f(aux_dir+"/format_proof_"+case_name+".json");f<<"{\"ndims\":"<<ndim<<",\"nnz\":"<<coo.size()<<",\"full_CSF_coordinate_and_exact_COO_multiset_pass\":true,\"source_contribution_statements_unchanged_output_atomic_precision_promoted\":true}";}}else check_inputs(false);before.resize(offsets.back());ck(cudaMemcpy(before.data(),dU,before.size()*4,cudaMemcpyDeviceToHost));for(size_t j=offsets[mode];j<offsets[mode+1];j++)if(before[j]!=0.0f)throw std::runtime_error("Targetoutputnotzeroatmodeinput");prefix.insert(prefix.end(),{double(case_id),double(mode)});for(auto v:before){if(!std::isfinite(v))throw std::runtime_error("Nonfiniteactualfactorinput");prefix.push_back(v);}bool repeated=true;for(int m=0;m<ndim;m++)if(m!=mode)for(size_t row=0;row<dims[m];row++)for(int r=1;r<mm_rank;r++){uint32_t a,b;memcpy(&a,&before[offsets[m]+row*mm_rank],4);memcpy(&b,&before[offsets[m]+row*mm_rank+r],4);repeated&=a==b;}reports.back().repeated&=repeated;gold.assign(dims[mode]*mm_rank,0);if(repeated){std::vector<long double>g(dims[mode],0);for(auto&x:coo){long double v=x.v;for(int m=0;m<ndim;m++)if(m!=mode)v*=before[offsets[m]+size_t(x.i[m])*mm_rank];g[x.i[mode]]+=v;}for(size_t row=0;row<dims[mode];row++)for(int r=0;r<mm_rank;r++)gold[row*mm_rank+r]=g[row];}else for(auto&x:coo)for(int r=0;r<mm_rank;r++){long double v=x.v;for(int m=0;m<ndim;m++)if(m!=mode)v*=before[offsets[m]+size_t(x.i[m])*mm_rank+r];gold[size_t(x.i[mode])*mm_rank+r]+=v;}}
void mm_mode_end(int mode,float*dU,const unsigned int*,const TiledTensor*){ck(cudaDeviceSynchronize());double_readback.resize(double_count+2*GUARD);ck(cudaMemcpy(double_readback.data(),double_base,double_readback.size()*8,cudaMemcpyDeviceToHost));std::vector<float> projected(double_count);for(size_t j=0;j<double_count;j++)projected[j]=(float)double_readback[GUARD+j];ck(cudaMemcpy(original_output,projected.data(),projected.size()*4,cudaMemcpyHostToDevice));ck(cudaFree(double_base));double_base=nullptr;double_out=nullptr;ck(cudaDeviceSynchronize());Observe timer;for(size_t j=0;j<GUARD;j++)if(double_readback[j]!=GUARD_VALUE||double_readback[GUARD+double_count+j]!=GUARD_VALUE)scientific_ok=false;for(size_t j=0;j<double_count;j++){long double delta=fabsl((long double)double_readback[GUARD+j]-gold[j]),budget=.01L+2e-5L*fabsl(gold[j]);if(!std::isfinite(delta)||delta>budget)scientific_ok=false;}outputs.insert(outputs.end(),double_readback.begin(),double_readback.end());std::vector<float>got(offsets.back());ck(cudaMemcpy(got.data(),dU,got.size()*4,cudaMemcpyDeviceToHost));check_inputs(false);auto&rep=reports.back();for(size_t j=0;j<got.size();j++){if(!std::isfinite(got[j]))scientific_ok=false;if(j<offsets[mode]||j>=offsets[mode+1]){uint32_t a,b;memcpy(&a,&got[j],4);memcpy(&b,&before[j],4);if(a!=b)scientific_ok=false;}}for(size_t j=0;j<gold.size();j++){long double delta=fabsl((long double)got[offsets[mode]+j]-gold[j]),budget=.01L+2e-5L*fabsl(gold[j]);rep.max_abs=std::max(rep.max_abs,(double)delta);rep.max_budget_ratio=std::max(rep.max_budget_ratio,(double)(delta/budget));if(!std::isfinite(delta)||delta>budget)scientific_ok=false;}outputs.insert(outputs.end(),{double(case_id),double(mode)});for(auto v:got)outputs.push_back(v);for(auto v:gold)outputs.push_back((double)v);rep.modes++;}
static void print_reports(){printf("[");for(size_t i=0;i<reports.size();i++){auto&q=reports[i];printf("%s{\"name\":\"%s\",\"ndims\":%d,\"rank\":%d,\"nonzeros\":%zu,\"modes_checked\":%d,\"all_input_factor_columns_proven_repeated\":%s,\"max_independent_abs_error\":%.17g,\"max_independent_error_over_budget\":%.17g}",i?",":"",q.name.c_str(),q.nd,q.rank,q.nnz,q.modes,q.repeated?"true":"false",q.max_abs,q.max_budget_ratio);}printf("]");}
extern "C" int mm_run(const char*fixture,const char*canon,const char*aux,MMCallback cb,int prep){try{prepare=prep;mm_callback=cb;canonical_dir=canon;fs::create_directories(canonical_dir);fs::create_directories(aux);std::string pattern=std::string(aux)+"/process_"+std::to_string(getpid())+"_XXXXXX";std::vector<char> tmp(pattern.begin(),pattern.end());tmp.push_back(0);if(!mkdtemp(tmp.data()))throw std::runtime_error("Auxmkdtempfailed");aux_dir=tmp.data();struct Case{const char*name;int r,w,s,f;};Case cases[]={{"toy",32,1,1,128},{"control3D",7,2,2,128},{"longFiber4D",3,2,2,16},{"sourceSize4D",32,4,1,128}};
 for(trial_id=0;trial_id<=(prepare?0:5);trial_id++){prefix.clear();outputs.clear();reports.clear();scientific_ok=true;excluded=0;auto start=Clock::now();for(case_id=0;case_id<4;case_id++){auto&q=cases[case_id];case_name=q.name;std::vector<std::string>args={"mmcsf","-i",std::string(fixture)+"/"+q.name+".tns","-m","0","-R",std::to_string(q.r),"-w",std::to_string(q.w),"-s",std::to_string(q.s),"-f",std::to_string(q.f),"-b","128"};std::vector<char*>argv;for(auto&s:args)argv.push_back(s.data());int status=original_mmcsf_main(argv.size(),argv.data());if(status||reports.back().modes!=reports.back().nd||!allocations.empty())scientific_ok=false;}ck(cudaDeviceSynchronize());double seconds=std::chrono::duration<double>(Clock::now()-start).count()-excluded;std::vector<double>values=prefix;values.insert(values.end(),outputs.begin(),outputs.end());if(trial_id==0){printf("STUDY_PREPARE_OR_WARMUP correct=%s prefix_values=%zu output_values=%zu cases=",scientific_ok?"true":"false",prefix.size(),values.size());print_reports();printf("\n");fflush(stdout);if(!scientific_ok){raw(aux_dir+"/rejected_warmup_fullstate.bin",values.data(),values.size()*8);return 2;}continue;}std::string out="output_trial"+std::to_string(trial_id)+".bin";raw(out,values.data(),values.size()*8);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":null,\"max_rel_error\":null,\"timing_region\":\"qualified_full_source_pipeline_including_FP64_output_allocation_projection_minus_added_observations\",\"jit_excluded\":true,\"internal_repeats\":1,\"full_actual_CSF_inputs_bit_identical\":true,\"all_readonly_tensor_storage_unchanged\":true,\"all_nontarget_factor_fields_unchanged\":%s,\"cases\":",trial_id,seconds,scientific_ok?"true":"false",values.size(),scientific_ok?"true":"false");print_reports();printf(",\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",out.c_str(),values.size());fflush(stdout);if(!scientific_ok)return 3;}
 printf("STUDY_ACTUAL_DISPATCH_COUNTS");for(int k=0;k<7;k++)printf(" op%d=%lld",k,dispatch_counts[k]);printf("\n");return 0;}catch(const std::exception&e){fprintf(stderr,"MMCSF_STUDY_REJECTED %s\n",e.what());return 4;}}
